class Solution:
    def maxGoodNumber(self, num: int, sum: int) -> str:
        full, rem = divmod(sum, 9)
        if full + (rem > 0) > num:
            return ""
        return "9" * full + (str(rem) if rem else "") + "0" * (num - full - (rem > 0))

c.cpp:
class Solution {
public:
    string maxGoodNumber(int num, int sum) {
        int full = sum / 9, rem = sum % 9;
        int used = full + (rem > 0);
        if (used > num) return "";
        string res(full, '9');
        if (rem) res += char('0' + rem);
        res += string(num - used, '0');
        return res;
    }
};

c.java:
class Solution {
    public String maxGoodNumber(int num, int sum) {
        int full = sum / 9, rem = sum % 9;
        int used = full + (rem > 0 ? 1 : 0);
        if (used > num) return "";
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < full; i++) sb.append('9');
        if (rem > 0) sb.append((char)('0' + rem));
        for (int i = used; i < num; i++) sb.append('0');
        return sb.toString();
    }
}

