var maxGoodNumber = function(num, sum) {
    const full = Math.floor(sum / 9), rem = sum % 9;
    const used = full + (rem > 0 ? 1 : 0);
    if (used > num) return "";
    return "9".repeat(full) + (rem ? String(rem) : "") + "0".repeat(num - used);
};
